-- Deterministic local/test fixture for Phase 2 case 05: Mamari provenance.
-- This fixture depends on the Phase 1 fixture for Paula Rossetti and Rome.

begin;

set local lock_timeout = '5s';
set local statement_timeout = '30s';

do $$
begin
    if not exists (
        select 1 from entities.entity
        where id = '10000000-0000-4000-8000-000000000001'::uuid
          and entity_type = 'agent'
    ) then
        raise exception 'Phase 2 Mamari fixture requires the Phase 1 fixture to be loaded first.';
    end if;

    if not exists (
        select 1 from entities.entity
        where id = '20000000-0000-4000-8000-000000000002'::uuid
          and entity_type = 'place'
    ) then
        raise exception 'Phase 2 Mamari fixture requires the Phase 1 Rome place.';
    end if;
end;
$$;

-- Reserved Phase 2 fixture UUID ranges are replaced atomically on each load.
delete from knowledge.claim_evidence
where id >= '61000000-0000-4000-8000-000000000000'::uuid
  and id <  '61000000-0000-4000-8000-000000000200'::uuid;

