-- Event evidence. Excerpts are source wording, never internal event labels.
insert into knowledge.claim_evidence (id, claim_id, source_id, relationship, locator, excerpt)
select
    ('61000000-0000-4000-8000-' || right(claim.id::text, 12))::uuid,
    claim.id,
    case when claim.asserted_by_agent_id = '10000000-0000-4000-8000-000000000001'::uuid
         then '41000000-0000-4000-8000-000000000001'::uuid
         else '41000000-0000-4000-8000-000000000002'::uuid end,
    'supports',
    case when claim.asserted_by_agent_id = '10000000-0000-4000-8000-000000000001'::uuid
         then 'Provenance field > Paula account'
         else 'Provenance history paragraph' end,
    case
        when claim.subject_id = '81000000-0000-4000-8000-000000000001'::uuid
            then 'sacado por el Padre Hippolyte Roussel desde Rapa Nui a Tahiti; entregada al arzobispo Tepano Jaussen'
        when claim.subject_id = '81000000-0000-4000-8000-000000000002'::uuid
            then 'apparently collected by Gaspar Zumbohm in 1870 and sent to him in Tahiti'
        when claim.subject_id = '81000000-0000-4000-8000-000000000003'::uuid
            then 'either by Jaussen in 1888'
        when claim.subject_id = '81000000-0000-4000-8000-000000000004'::uuid
            then 'or by the French navy in 1892 after his death'
        when claim.subject_id = '81000000-0000-4000-8000-000000000005'::uuid
            then 'moved to Braine-le-Comte in 1905'
        when claim.subject_id = '81000000-0000-4000-8000-000000000006'::uuid
            then 'moved to Grottaferrata in 1953'
        when claim.subject_id = '81000000-0000-4000-8000-000000000007'::uuid
            then 'moved to Rome in 1964'
        else null
    end
from knowledge.claim as claim
where claim.subject_id >= '81000000-0000-4000-8000-000000000001'::uuid
  and claim.subject_id <= '81000000-0000-4000-8000-000000000007'::uuid;

